/** SearchActivityV2 layout and keyboard; requests use the ordinary searchable Site task. */
public final class LiulangSearchActivity extends Activity {
    LiulangResources res;FrameLayout root;ViewGroup page;EditText keyword;ImageView background,searchButton,mic;
    View results,loading,empty;LiulangFlow hot,records;TextView hotHeading;HorizontalGridView sites,cards;VerticalGridView keyboard;
    ArrayObjectAdapter siteRows,cardRows,keyRows;final Handler main=new Handler(Looper.getMainLooper());
    final ThreadPoolExecutor worker=new ThreadPoolExecutor(4,4,10,TimeUnit.SECONDS,new LinkedBlockingQueue<Runnable>());
    final List<Future<?>> tasks=new ArrayList<>();final LinkedHashMap<String,Result> found=new LinkedHashMap<>();
    final List<String> history=new ArrayList<>();long generation,wordGeneration;Integer configuration;String query="";Result selected;boolean numeric,closed;
    final Runnable suggest=()->suggestions();
    static final class Result {final SiteFeed.Site site;final List<JSONObject> items=new ArrayList<>();int page=1;boolean more=true,busy;Result(SiteFeed.Site site){this.site=site;}}
    @Override public void onCreate(Bundle saved){
        super.onCreate(saved);LiulangSurfaces.window(this);setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);getWindow().setFlags(1024,1024);getWindow().getDecorView().setSystemUiVisibility(5894);
        SiteFeed.initialize(this);MetadataSettings.initialize(this);res=new LiulangResources(this);root=new FrameLayout(res);root.setBackgroundColor(Color.BLACK);setContentView(root);
        background=new ImageView(res);background.setScaleType(ImageView.ScaleType.CENTER_CROP);root.addView(background,new FrameLayout.LayoutParams(-1,-1));
        View mask=new View(res);mask.setBackground(res.drawable("bg_hero_mask_v"));root.addView(mask,new FrameLayout.LayoutParams(-1,-1));View shade=new View(res);shade.setBackgroundColor(0x33000000);root.addView(shade,new FrameLayout.LayoutParams(-1,-1));
        page=(ViewGroup)res.inflate("activity_search",root);root.addView(page,new FrameLayout.LayoutParams(-1,-1));keyword=res.find(page,"keyword");mic=res.find(page,"mic");mic.setVisibility(android.speech.SpeechRecognizer.isRecognitionAvailable(this)?View.VISIBLE:View.GONE);
        keyword.setTextSize(14);keyword.setTextColor(Color.WHITE);keyword.setHintTextColor(0xffcccccc);keyword.setBackground(res.drawable("selector_tmdb_input"));keyword.setPadding(res.dp(12),0,res.dp(12),0);keyword.setShowSoftInputOnFocus(false);
        LinearLayout input=(LinearLayout)keyword.getParent();LinearLayout.LayoutParams inputParams=new LinearLayout.LayoutParams(0,res.dp(32),1);keyword.setLayoutParams(inputParams);
        searchButton=new ImageView(res);searchButton.setBackground(res.drawable("selector_tmdb_search"));searchButton.setImageDrawable(res.drawable("ic_keyboard_search"));searchButton.setPadding(res.dp(4),res.dp(4),res.dp(4),res.dp(4));searchButton.setFocusable(true);searchButton.setFocusableInTouchMode(true);searchButton.setContentDescription("搜索");LinearLayout.LayoutParams buttonParams=new LinearLayout.LayoutParams(res.dp(32),res.dp(32));buttonParams.leftMargin=res.dp(6);input.addView(searchButton,buttonParams);searchButton.setOnClickListener(v->search());
        ViewGroup column=(ViewGroup)input.getParent();ViewGroup.LayoutParams columnParams=column.getLayoutParams();columnParams.width=res.dp(240);column.setLayoutParams(columnParams);
        keyboard=res.find(page,"keyboard");keyboard.setNumColumns(7);keyboard.setColumnWidth(res.dp(30));keyboard.setHorizontalSpacing(res.dp(4));keyboard.setVerticalSpacing(res.dp(4));keyboard.setItemAnimator(null);keyboard.setLayoutParams(new LinearLayout.LayoutParams(res.dp(240),res.dp(140)));keyRows=new ArrayObjectAdapter(new Keys());keyboard.setAdapter(new ItemBridgeAdapter(keyRows));keys();
        hot=res.find(page,"wordRecycler");records=res.find(page,"recordRecycler");hotHeading=res.find(page,"word");heading(hotHeading);ViewGroup recordSection=res.find(page,"recordLayout");if(recordSection.getChildAt(0) instanceof TextView)heading((TextView)recordSection.getChildAt(0));
        sites=res.find(page,"siteRecycler");cards=res.find(page,"recycler");siteRows=new ArrayObjectAdapter(new Sites());cardRows=new ArrayObjectAdapter(new Posters());sites.setAdapter(new ItemBridgeAdapter(siteRows));cards.setAdapter(new ItemBridgeAdapter(cardRows));sites.setHorizontalSpacing(res.dp(12));sites.setRowHeight(-2);sites.setItemAnimator(null);cards.setHorizontalSpacing(res.dp(16));cards.setItemAnimator(null);cards.setItemViewCacheSize(10);
        results=res.find(page,"resultSection");loading=res.find(page,"posterProgress");empty=res.find(page,"posterEmpty");cards.setOnChildSelectedListener((parent,child,index,id)->{if(selected!=null&&index>=selected.items.size()-7)nextPage();});
        keyword.setOnEditorActionListener((view,action,event)->{search();return true;});keyword.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){main.removeCallbacks(suggest);main.postDelayed(suggest,250);}public void afterTextChanged(Editable text){}});
        mic.setOnClickListener(v->{try{startActivityForResult(new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM),71);}catch(android.content.ActivityNotFoundException absent){((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(keyword,InputMethodManager.SHOW_IMPLICIT);}});
        readHistory();drawHistory();hotWords();background.setImageDrawable(LiulangBackdrop.background(true));
        String initial=saved==null?getIntent().getStringExtra("keyword"):saved.getString("keyword");if(initial!=null&&!initial.isEmpty()){keyword.setText(initial);keyword.setSelection(initial.length());search();}else keyword.requestFocus();
    }
    void heading(TextView title){ViewGroup parent=(ViewGroup)title.getParent();int index=parent.indexOfChild(title);ViewGroup.LayoutParams old=title.getLayoutParams();parent.removeView(title);LinearLayout row=new LinearLayout(res);row.setGravity(Gravity.CENTER_VERTICAL);View bar=new View(res);bar.setBackground(res.drawable("shape_red_bar"));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(res.dp(4),res.dp(16));p.rightMargin=res.dp(10);row.addView(bar,p);title.setTextSize(20);title.setTypeface(title.getTypeface(),1);title.setTextColor(0xffcccccc);row.addView(title,new LinearLayout.LayoutParams(-2,-2));parent.addView(row,index,old);}
    static String prefs(String key){try{return (String)Class.forName("r7.g").getMethod("t",String.class,String.class).invoke(null,key,"");}catch(ReflectiveOperationException ignored){return "";}}
    void readHistory(){try{JSONArray array=new JSONArray(prefs("keyword"));for(int i=0;i<array.length();i++){String value=array.optString(i);if(!value.isEmpty())history.add(value);}}catch(JSONException ignored){}}
    void saveHistory(){history.remove(query);history.add(0,query);while(history.size()>9)history.remove(history.size()-1);try{Class.forName("r7.g").getMethod("I",Object.class,String.class).invoke(null,new JSONArray(history).toString(),"keyword");}catch(ReflectiveOperationException ignored){}drawHistory();}
    void drawHistory(){res.find(page,"recordLayout").setVisibility(history.isEmpty()?View.GONE:View.VISIBLE);chips(records,history,true);}
    void chips(LiulangFlow flow,List<String> words,boolean saved){flow.removeAllViews();for(String word:words){TextView text=(TextView)res.inflate(saved?"adapter_search_record":"adapter_search_word",flow);text.setText(word);LiulangStyle.capsule(text);text.setOnClickListener(v->{keyword.setText(word);keyword.setSelection(word.length());search();});if(saved)text.setOnLongClickListener(v->{history.remove(word);try{Class.forName("r7.g").getMethod("I",Object.class,String.class).invoke(null,new JSONArray(history).toString(),"keyword");}catch(ReflectiveOperationException ignored){}drawHistory();return true;});flow.addView(text);}}
    void hotWords(){try{Object values=Class.forName("com.fongmi.android.tv.bean.Hot").getMethod("get",String.class).invoke(null,prefs("hot"));if(values instanceof List)chips(hot,(List<String>)values,false);}catch(ReflectiveOperationException ignored){}wordGeneration++;long token=wordGeneration;worker.execute(()->{try{String json=publicJson("https://api.web.360kan.com/v1/rank?cat=1");Object values=Class.forName("com.fongmi.android.tv.bean.Hot").getMethod("get",String.class).invoke(null,json);if(values instanceof List)main.post(()->{if(!closed&&token==wordGeneration&&keyword.length()==0)chips(hot,(List<String>)values,false);});}catch(Exception ignored){}});}
    void suggestions(){if(closed)return;String word=keyword.getText().toString().trim();if(word.isEmpty()){hotHeading.setText("热搜");hotWords();return;}hotHeading.setText("联想");long token=++wordGeneration;worker.execute(()->{try{String text=publicJson("https://suggest.video.iqiyi.com/?if=mobile&key="+java.net.URLEncoder.encode(word,"UTF-8"));JSONObject response=new JSONObject(text);JSONArray list=response.optJSONArray("data");List<String> words=new ArrayList<>();for(int i=0;list!=null&&i<list.length()&&words.size()<30;i++){JSONObject row=list.optJSONObject(i);String title=row==null?list.optString(i):row.optString("name",row.optString("title"));if(!title.isEmpty())words.add(title);}main.post(()->{if(!closed&&token==wordGeneration)chips(hot,words,false);});}catch(Exception ignored){}});}
    String publicJson(String address)throws Exception{java.net.HttpURLConnection connection=(java.net.HttpURLConnection)new java.net.URL(address).openConnection();connection.setConnectTimeout(5000);connection.setReadTimeout(5000);connection.setRequestProperty("User-Agent","Mozilla/5.0");if(address.contains("360kan"))connection.setRequestProperty("Referer","https://www.360kan.com/rank/general");try(java.io.InputStream in=connection.getInputStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] buffer=new byte[8192];for(int n;(n=in.read(buffer))!=-1;){if(out.size()+n>1024*1024)throw new java.io.IOException("Suggestion response too large");out.write(buffer,0,n);}return out.toString("UTF-8");}finally{connection.disconnect();}}
    void keys(){List<String> labels=new ArrayList<>(Arrays.asList("▦","‹","›","⌫","⌨","⌂"));String letters=numeric?"ㄅㄆㄇㄈㄉㄊㄋㄌㄍㄎㄏㄐㄑㄒㄓㄔㄕㄖㄗㄘㄙㄧㄨㄩㄚㄛㄜㄝㄞㄟㄠㄡㄢㄣㄤㄥㄦ0123456789":"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";for(int i=0;i<letters.length();i++)labels.add(letters.substring(i,i+1));keyRows.setItems(labels,null);}
    void key(String text){int cursor=Math.max(0,keyword.getSelectionStart());switch(text){case "▦":numeric=!numeric;keys();return;case "‹":keyword.setSelection(Math.max(0,cursor-1));return;case "›":keyword.setSelection(Math.min(keyword.length(),cursor+1));return;case "⌫":if(cursor>0)keyword.getText().delete(cursor-1,cursor);return;case "⌨":keyword.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(keyword,InputMethodManager.SHOW_IMPLICIT);return;case "⌂":finish();return;default:keyword.getText().insert(cursor,text);}}
    void search(){String text=keyword.getText().toString().trim();if(text.isEmpty())return;cancel();query=text;saveHistory();configuration=SiteFeed.configId();found.clear();selected=null;siteRows.clear();cardRows.clear();results.setVisibility(View.VISIBLE);sites.setVisibility(View.INVISIBLE);loading.setVisibility(View.VISIBLE);empty.setVisibility(View.GONE);((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(keyword.getWindowToken(),0);final long token=generation;List<SiteFeed.Site> providers=new ArrayList<>();for(SiteFeed.Site site:SiteFeed.searchSites())if(SiteFeed.searchable(site)&&!Boolean.TRUE.equals(SiteFeed.invoke(site.raw,"isHide")))providers.add(site);final int[] remaining={providers.size()};if(providers.isEmpty()){loading.setVisibility(View.GONE);empty.setVisibility(View.VISIBLE);return;}for(SiteFeed.Site site:providers){Future<?> task=worker.submit(()->{JSONObject body=null;try{body=searchBody(site,text,1);}catch(Exception ignored){}JSONObject result=body;main.post(()->{if(!valid(token))return;if(result!=null){List<JSONObject> values=CspHomeData.items(result,1000);if(!values.isEmpty()){Result entry=new Result(site);entry.items.addAll(values);entry.more=result.optInt("pagecount",0)!=1;found.put(site.key,entry);siteRows.add(entry);sites.setVisibility(View.VISIBLE);if(selected==null)select(entry);}}if(--remaining[0]==0){loading.setVisibility(View.GONE);empty.setVisibility(found.isEmpty()?View.VISIBLE:View.GONE);}});});tasks.add(task);}}
    JSONObject searchBody(SiteFeed.Site site,String text,int page)throws Exception{synchronized(site.raw){if(Thread.currentThread().isInterrupted())throw new InterruptedException();Class<?> model=Class.forName("com.fongmi.android.tv.bean.Site");Object task=Class.forName("B3.i").getConstructor(model,String.class,boolean.class,String.class).newInstance(site.raw,text,false,String.valueOf(page));Object result=((java.util.concurrent.Callable<?>)task).call();if(result==null)throw new IllegalStateException();return new JSONObject(result.toString());}}
    boolean valid(long token){return !closed&&generation==token&&Objects.equals(configuration,SiteFeed.configId());}
    void select(Result value){selected=value;cardRows.setItems(value.items,null);siteRows.notifyArrayItemRangeChanged(0,siteRows.size());cards.setSelectedPosition(0);loading.setVisibility(View.GONE);empty.setVisibility(value.items.isEmpty()?View.VISIBLE:View.GONE);}
    void nextPage(){Result value=selected;if(value==null||value.busy||!value.more)return;value.busy=true;long token=generation;int number=value.page+1;String text=query;tasks.add(worker.submit(()->{try{JSONObject body=searchBody(value.site,text,number);List<JSONObject> values=CspHomeData.items(body,1000);main.post(()->{if(!valid(token))return;value.busy=false;Set<String> ids=new HashSet<>();for(JSONObject row:value.items)ids.add(LiulangHome.id(row));List<JSONObject> additions=new ArrayList<>();for(JSONObject row:values)if(ids.add(LiulangHome.id(row)))additions.add(row);value.items.addAll(additions);value.page=number;value.more=!additions.isEmpty()&&(body.optInt("pagecount",0)==0||number<body.optInt("pagecount"));if(selected==value)cardRows.addAll(cardRows.size(),additions);});}catch(Exception ignored){main.post(()->{if(valid(token))value.busy=false;});}}));}
    void cancel(){generation++;for(Future<?> task:tasks)task.cancel(true);tasks.clear();worker.getQueue().clear();}
    @Override public boolean dispatchKeyEvent(KeyEvent event){int code=event.getKeyCode();View focus=getCurrentFocus();if(code==KeyEvent.KEYCODE_BACK){if(event.getAction()==KeyEvent.ACTION_UP&&!event.isCanceled()){if(results.getVisibility()==View.VISIBLE){cancel();results.setVisibility(View.GONE);keyword.requestFocus();}else finish();}return true;}if(code==KeyEvent.KEYCODE_DPAD_UP&&NativeCspUi.descendant(focus,cards)){if(event.getAction()==KeyEvent.ACTION_DOWN)sites.requestFocus();return true;}if(code==KeyEvent.KEYCODE_DPAD_DOWN&&NativeCspUi.descendant(focus,sites)){if(event.getAction()==KeyEvent.ACTION_DOWN)cards.requestFocus();return true;}return super.dispatchKeyEvent(event);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==71&&result==RESULT_OK&&data!=null){ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty()){keyword.setText(words.get(0));search();}}}
    @Override protected void onSaveInstanceState(Bundle state){state.putString("keyword",keyword.getText().toString());super.onSaveInstanceState(state);}
    @Override protected void onDestroy(){closed=true;cancel();wordGeneration++;main.removeCallbacksAndMessages(null);worker.shutdownNow();if(cards!=null)for(int i=0;i<cards.getChildCount();i++){ImageView image=res.find(cards.getChildAt(i),"image");if(image!=null)NativeCspUi.releaseHomeImage(image);}super.onDestroy();}
    final class Keys extends Presenter {public Presenter$ViewHolder onCreateViewHolder(ViewGroup p){TextView key=(TextView)res.inflate("adapter_tmdb_keyboard_text",p);key.setLayoutParams(new ViewGroup.LayoutParams(res.dp(30),res.dp(30)));key.setTextSize(14);return new Presenter$ViewHolder(key);}public void onBindViewHolder(Presenter$ViewHolder h,Object value){TextView text=(TextView)h.view;String label=(String)value;int index=Arrays.asList("▦","‹","›","⌫","⌨","⌂").indexOf(label);text.setCompoundDrawables(null,null,null,null);text.setText(index<0?label:"");if(index>=0){String[] icons={"ic_keyboard_remote","ic_keyboard_left","ic_keyboard_right","ic_keyboard_back","ic_keyboard","ic_setting_home"};android.graphics.drawable.Drawable icon=res.drawable(icons[index]);icon.setBounds(0,0,res.dp(20),res.dp(20));text.setPadding(res.dp(5),0,0,0);text.setCompoundDrawables(icon,null,null,null);text.setContentDescription(new String[]{"切换键盘","光标向左","光标向右","删除","输入法","首页"}[index]);}else text.setPadding(0,0,0,0);h.view.setOnClickListener(v->key(label));}public void onUnbindViewHolder(Presenter$ViewHolder h){h.view.setOnClickListener(null);}}
    final class Sites extends Presenter {public Presenter$ViewHolder onCreateViewHolder(ViewGroup p){TextView view=(TextView)res.inflate("adapter_type",p);LiulangStyle.capsule(view);return new Presenter$ViewHolder(view);}public void onBindViewHolder(Presenter$ViewHolder h,Object value){Result result=(Result)value;((TextView)h.view).setText(result.site.name+"  "+result.items.size());h.view.setSelected(selected==result);h.view.setOnClickListener(v->select(result));h.view.setOnFocusChangeListener((v,focus)->{if(focus&&selected!=result)select(result);});}public void onUnbindViewHolder(Presenter$ViewHolder h){h.view.setOnClickListener(null);h.view.setOnFocusChangeListener(null);}}
    final class Posters extends Presenter {public Presenter$ViewHolder onCreateViewHolder(ViewGroup p){View view=res.inflate("adapter_vod_rect",p);view.setLayoutParams(new ViewGroup.LayoutParams(res.dp(120),-2));view.setOnFocusChangeListener((v,focus)->{v.animate().cancel();v.animate().scaleX(focus?1.08f:1).scaleY(focus?1.08f:1).setDuration(150).start();});return new Presenter$ViewHolder(view);}public void onBindViewHolder(Presenter$ViewHolder h,Object object){JSONObject value=(JSONObject)object;res.<TextView>find(h.view,"name").setText(value.optString("vod_name"));ImageView image=res.find(h.view,"image");NativeCspUi.homeImage(image,value.optString("vod_name"),value.optString("vod_pic"));Result source=selected;h.view.setOnClickListener(v->{if(source!=null)NativeRouting.openCspResource(LiulangSearchActivity.this,source.site.key,value);});PosterSearch.attach(LiulangSearchActivity.this,h.view,value);}public void onUnbindViewHolder(Presenter$ViewHolder h){PosterSearch.detach(h.view);h.view.setOnClickListener(null);NativeCspUi.releaseHomeImage(res.find(h.view,"image"));}}
}
